class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def numComponents(head, nums):
    # Store nums in a set for O(1) membership checking
    num_set = set(nums)
    count = 0
    in_component = False
    node = head

    while node:
        # If current node is in nums, check if it's the start of a component
        if node.val in num_set:
            if not in_component:
                count += 1
                in_component = True
        else:
            in_component = False
        node = node.next

    return count
